const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7'); // You must include this line

async function getInfoAsync(obj) {
  return await new Promise((resolve, reject) => {
    obj.getInfo((res, err) => (err ? reject(err) : resolve(res)));
  });
}

function maskS2SR(img) {
  var scl = img.select('SCL');
  var cloud = scl.eq(3).or(scl.eq(8)).or(scl.eq(9)).or(scl.eq(10)).or(scl.eq(11));
  var ndwi = img.normalizedDifference(['B3', 'B8']).rename('NDWI');
  var waterMask = ndwi.gt(0);
  var mask = cloud.not().and(waterMask);
  return img.updateMask(mask).copyProperties(img, img.propertyNames());
}

function maskS2TOA(img) {
  var qa = img.select('QA60');
  var cloud = qa.bitwiseAnd(1 << 10).neq(0).or(qa.bitwiseAnd(1 << 11).neq(0));
  var ndwi = img.normalizedDifference(['B3', 'B8']).rename('NDWI');
  var waterMask = ndwi.gt(0);
  var mask = cloud.not().and(waterMask);
  return img.updateMask(mask).copyProperties(img, img.propertyNames());
}

function prepareS2SR(start, end, aoi) {
  var col = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(aoi)
    .filterDate(start, end)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80))
    .map(maskS2SR);
  return col;
}

function prepareS2TOA(start, end, aoi) {
  var col = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(aoi)
    .filterDate(start, end)
    .filter(ee.Filter.lt('CLOUD_COVERAGE_ASSESSMENT', 80))
    .map(maskS2TOA);
  return col;
}

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    var plumePt = ee.Geometry.Point([-136.275745, 69.264212]);
    var oceanPt = ee.Geometry.Point([-137.786365, 69.803894]);
    var bufM = 1000;
    var plume = plumePt.buffer(bufM);
    var ocean = oceanPt.buffer(bufM);
    var unionAOI = plume.union(ocean);
    var start = '2017-07-19';
    var end = '2017-07-20';

    // 2. Data Acquisition & Check (with fallbacks)
    var dataset = null;
    var used = null;

    var colSR = prepareS2SR(start, end, unionAOI);
    var nSR = await getInfoAsync(colSR.size());
    if (nSR > 0) {
      dataset = colSR;
      used = 'S2_SR';
    } else {
      var colTOA = prepareS2TOA(start, end, unionAOI);
      var nTOA = await getInfoAsync(colTOA.size());
      if (nTOA > 0) {
        dataset = colTOA;
        used = 'S2_TOA';
      } else {
        // widen window ±3 days
        var startW = '2017-07-16';
        var endW = '2017-07-22';
        var colSRw = prepareS2SR(startW, endW, unionAOI);
        var nSRw = await getInfoAsync(colSRw.size());
        if (nSRw > 0) {
          dataset = colSRw;
          used = 'S2_SR(±3d)';
        } else {
          var colTOAw = prepareS2TOA(startW, endW, unionAOI);
          var nTOAw = await getInfoAsync(colTOAw.size());
          if (nTOAw > 0) {
            dataset = colTOAw;
            used = 'S2_TOA(±3d)';
          } else {
            console.log('Collections: S2_SR=0, S2_TOA=0, widened=0');
            console.log('C1');
            return;
          }
        }
      }
    }

    var nImgs = await getInfoAsync(dataset.size());
    var image = dataset.mosaic().clip(unionAOI);

    // 3. Pixel counts to detect C2 and cloud %
    var scale = 1000;

    // Valid pixels per ROI after masking: count of B3 pixels
    var plumeCount = await getInfoAsync(
      image.select('B3').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: plume,
        scale: scale,
        maxPixels: 1e9
      }).get('B3')
    );
    var oceanCount = await getInfoAsync(
      image.select('B3').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: ocean,
        scale: scale,
        maxPixels: 1e9
      }).get('B3')
    );
    if (!plumeCount || !oceanCount || plumeCount === 0 || oceanCount === 0) {
      console.log(`${used} Images: ${nImgs}; Valid px (plume,ocean): ${plumeCount || 0}, ${oceanCount || 0}`);
      console.log('C2');
      return;
    }

    // Cloud percent over AOI (using SCL or QA60, regardless of masking)
    var cloudPct;
    if (used.startsWith('S2_SR')) {
      var sclMosaic = ee.ImageCollection('COPERNICUS/S2_SR')
        .filterBounds(unionAOI)
        .filterDate('2017-07-16', '2017-07-22')
        .mosaic()
        .select('SCL')
        .clip(unionAOI);
      var cloudMask = sclMosaic.eq(3).or(sclMosaic.eq(8)).or(sclMosaic.eq(9)).or(sclMosaic.eq(10)).or(sclMosaic.eq(11));
      var cloudCount = await getInfoAsync(
        cloudMask.rename('c').reduceRegion({
          reducer: ee.Reducer.sum(),
          geometry: unionAOI,
          scale: scale,
          maxPixels: 1e9
        }).get('c')
      );
      var totalCount = await getInfoAsync(
        ee.Image.constant(1).rename('o').reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: unionAOI,
          scale: scale,
          maxPixels: 1e9
        }).get('o')
      );
      cloudPct = totalCount ? (100 * (cloudCount || 0) / totalCount) : null;
    } else {
      var qaMosaic = ee.ImageCollection('COPERNICUS/S2')
        .filterBounds(unionAOI)
        .filterDate('2017-07-16', '2017-07-22')
        .mosaic()
        .select('QA60')
        .clip(unionAOI);
      var cloudMaskTOA = qaMosaic.bitwiseAnd(1 << 10).neq(0).or(qaMosaic.bitwiseAnd(1 << 11).neq(0));
      var cloudCount = await getInfoAsync(
        cloudMaskTOA.rename('c').reduceRegion({
          reducer: ee.Reducer.sum(),
          geometry: unionAOI,
          scale: scale,
          maxPixels: 1e9
        }).get('c')
      );
      var totalCount = await getInfoAsync(
        ee.Image.constant(1).rename('o').reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: unionAOI,
          scale: scale,
          maxPixels: 1e9
        }).get('o')
      );
      cloudPct = totalCount ? (100 * (cloudCount || 0) / totalCount) : null;
    }

    // 4. Calculation: NDTI, green reflectance, visible brightness
    var ndtiImg = image.normalizedDifference(['B4', 'B3']).rename('NDTI');
    var visMeanImg = image.select(['B2', 'B3', 'B4']).divide(10000).reduce(ee.Reducer.mean()); // pixelwise mean across VIS bands

    var ndtiPlume = await getInfoAsync(
      ndtiImg.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: plume,
        scale: scale,
        maxPixels: 1e9
      }).get('NDTI')
    );
    var ndtiOcean = await getInfoAsync(
      ndtiImg.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: ocean,
        scale: scale,
        maxPixels: 1e9
      }).get('NDTI')
    );
    var greenPlume = await getInfoAsync(
      image.select('B3').divide(10000).reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: plume,
        scale: scale,
        maxPixels: 1e9
      }).get('B3')
    );
    var greenOcean = await getInfoAsync(
      image.select('B3').divide(10000).reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: ocean,
        scale: scale,
        maxPixels: 1e9
      }).get('B3')
    );
    var visPlume = await getInfoAsync(
      visMeanImg.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: plume,
        scale: scale,
        maxPixels: 1e9
      }).get('mean')
    );
    var visOcean = await getInfoAsync(
      visMeanImg.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: ocean,
        scale: scale,
        maxPixels: 1e9
      }).get('mean')
    );

    // 5. Validation & Final Answer
    function invalid(x) {
      return x === null || x === undefined || isNaN(x);
    }
    if (invalid(ndtiPlume) || invalid(ndtiOcean) || invalid(greenPlume) || invalid(greenOcean) || invalid(visPlume) || invalid(visOcean) ||
        Math.abs(ndtiPlume) > 1.5 || Math.abs(ndtiOcean) > 1.5) {
      console.log(`${used} Images: ${nImgs}; Valid px (plume,ocean): ${plumeCount}, ${oceanCount}`);
      if (cloudPct !== null && cloudPct !== undefined) console.log(`Cloud% (AOI): ${cloudPct.toFixed(1)}`);
      console.log('C3');
      return;
    }

    var ndtiHigher = ndtiPlume > ndtiOcean;
    var visHigher = visPlume > visOcean;

    console.log(`${used} Images: ${nImgs}; Window: ${used.includes('±3d') ? '±3d' : 'day'}`);
    if (cloudPct !== null && cloudPct !== undefined) console.log(`Cloud% (AOI): ${cloudPct.toFixed(1)}`);
    console.log(`Valid px (plume,ocean): ${plumeCount}, ${oceanCount}`);
    console.log(`NDTI (plume, ocean): ${ndtiPlume.toFixed(3)}, ${ndtiOcean.toFixed(3)}`);
    console.log(`Green refl ρ (plume, ocean): ${greenPlume.toFixed(3)}, ${greenOcean.toFixed(3)}`);
    console.log(`VIS mean ρ (plume, ocean): ${visPlume.toFixed(3)}, ${visOcean.toFixed(3)}`);
    console.log(`Plume > Ocean in NDTI and VIS: ${ndtiHigher && visHigher}`);

    if (ndtiHigher && visHigher) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (e) {
    console.log(`Error: ${e}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
